"\r\n\r\nmsgid \"settings.channelMode.tarOnly\"\r\nmsgstr \"TAR only\"\r\n\r\nmsgid \"settings.channelMode.preferSftp\"\r\nmsgstr \"Prefer SFTP\"\r\n\r\nmsgid \"settings.channelMode.preferTar\"\r\nmsgstr \"Prefer TAR\"\r\n\r\nmsgid \"settings.channelMode.smartDesc\"\r\nmsgstr \"Auto-pick best channel by folder size and file count\"\r\n\r\nmsgid \"settings.channelMode.sftpOnlyDesc\"\r\nmsgstr \"Always transfer file by file; never use tar packing and no size-based routing\"\r\n\r\nmsgid \"settings.channelMode.tarOnlyDesc\"\r\nmsgstr \"Always use tar packing with no size-based routing; when packing is unavailable or fails, report the error instead of falling back to file-by-file. When the destination already exists the first attempt still goes file-by-file so conflicts can be detected; choosing Overwrite or Rename in the conflict prompt then continues with tar packing. A single file is always transferred file by file\"\r\n\r\nmsgid \"settings.channelMode.preferSftpDesc\"\r\nmsgstr \"Use tar only when clearly beneficial (requires many more files)\"\r\n\r\nmsgid \"settings.channelMode.preferTarDesc\"\r\nmsgstr \"Pack unless clearly worse (huge files); loose threshold\"\r\n\r\nmsgid \"notify.tarOnlyFailed\"\r\nmsgstr \"TAR-only mode: cannot transfer {name} - {reason}. Change Transfer channel mode to Smart / Prefer TAR in Settings, or fix the environment and retry\"\r\n\r\nmsgid \"tarchan.reason.localTarMissing\"\r\nmsgstr \"no usable tar command on this computer\"\r\n\r\nmsgid \"tarchan.reason.remoteTarMissing\"\r\nmsgstr \"no usable tar command on the remote server\"\r\n\r\nmsgid \"tarchan.reason.symlinkUnsupported\"\r\nmsgstr \"the folder contains symbolic links, which the packing channel does not support\"\r\n\r\nmsgid \"tarchan.reason.packFailed\"\r\nmsgstr \"packing or extracting the archive failed\"\r\n\r\nmsgid \"tarchan.reason.tarballFailed\"\r\nmsgstr \"transferring the archive file failed\"\r\n\r\nmsgid \"tarchan.reason.other\"\r\nmsgstr \"the packing channel is unavailable, see the log for details\"\r\n\r\nmsgid \"notify.tarOnlyInapplicable\"\r\nmsgstr \"TAR-only mode: {name} is not using the packed channel - {reason}. To send it as one archive, choose Overwrite in the directory conflict prompt, or delete the destination first and retry\"\r\n\r\nmsgid \"tarchan.reason.targetExists\"\r\nmsgstr \"the destination already exists, and an incremental transfer can only go through the per-file channel\"\r\n\r\nmsgid \"tarchan.reason.localPackFailed\"\r\nmsgstr \"packing the folder on this computer failed, possibly due to disk space or permissions\"\r\n\r\nmsgid \"tarchan.reason.remotePackFailed\"\r\nmsgstr \"packing or extracting on the remote server failed, possibly due to disk space or permissions\"\r\n\r\nmsgid \"tarchan.reason.localExtractFailed\"\r\nmsgstr \"extracting the archive on this computer failed, see the log for details\"\r\n\r\nmsgid \"tarchan.reason.nameEncodingUnsupported\"\r\nmsgstr \"the file names on the remote server cannot be decoded on this computer; switch to Smart or Prefer SFTP mode, or upgrade the tar command on the server\"\r\n\r\nmsgid \"transfer.batchUpload\"\r\nmsgstr \"{n} items from {dir}\"\r\n\r\nmsgid \"settings.exportPickHint\"\r\nmsgstr \"Välj vad som ska ingå i exportfilen.\"\r\n\r\nmsgid \"settings.exportSelectAll\"\r\nmsgstr \"Välj alla\"\r\n\r\nmsgid \"settings.exportDeselectAll\"\r\nmsgstr \"Rensa val\"\r\n\r\nmsgid \"settings.exportCatBookmarkData\"\r\nmsgstr \"Bokmärkesdata\"\r\n\r\nmsgid \"settings.hotkeyWheelHint\"\r\nmsgstr \"Hjulbindning, klicka för att spela in igen (listan kan inte längre rullas med hjulet)\"\r\n\r\nmsgid \"settings.panelHotkeyWheelBareWarning\"\r\nmsgstr \"Kopplat till {keys}; listan kan inte längre rullas med hjulet (lägg till Alt)\"\r\n\r\nmsgid \"settings.textCaretShape\"\r\nmsgstr \"Markörform (visare/redigerare)\"\r\nmsgid \"settings.textCaretShapeHint\"\r\nmsgstr \"Formen på markören som ritas i visaren. De tre valen motsvarar markören i Tabby-terminalen. Redigeraren använder systemmarkören.\"\r\nmsgid \"settings.caretShapeBlock\"\r\nmsgstr \"Block\"\r\nmsgid \"settings.caretShapeBeam\"\r\nmsgstr \"Lodrät streck\"\r\nmsgid \"settings.caretShapeUnderline\"\r\nmsgstr \"Understrykning\"\r\n";

